23	// Provider implements agent.Provider for OpenAI-compatible APIs.
24	type Provider struct {
25		client             *openaicompat.Client
26		model              string
27		modelPattern       string            // regex filter for auto-discovery; "" means first model
28		knownModels        map[string]string // catalog-recognized model IDs (modelID → catalogRef)
29		baseURL            string            // stored for lazy model discovery
30		apiKey             string            // stored for lazy model discovery
31		providerName       string
32		providerSystem     string
33		capabilities       *ProtocolCapabilities
34		usageCost          func(rawUsage string) (*agent.CostAttribution, bool)
35		serverAddress      string
36		serverPort         int
37		reasoningDefault   reasoningpolicy.Reasoning
38		modelReasoningWire map[string]string
39		logger             *slog.Logger
40	
41		// lazy model discovery — runs at most once per Provider instance
42		discoverOnce     sync.Once
43		discoverErr      error
44		discoveredModels []ScoredModel // full ranked list; populated on first use when model == ""
45	}
