47	// Config holds configuration for the OpenAI-compatible provider.
48	type Config struct {
49		BaseURL      string // e.g., "http://localhost:1234/v1" for LM Studio
50		APIKey       string // optional for local providers
51		Model        string // e.g., "qwen3.5-7b", "gpt-4o". Empty = auto-discover.
52		ProviderName string // logical provider identity; default "openai"
53		// ProviderSystem is the telemetry/cost system identity. When empty, it
54		// defaults to "openai". Concrete provider wrappers set their own type.
55		ProviderSystem string
56		ModelPattern   string // case-insensitive regex to prefer among auto-discovered models
57		// KnownModels maps concrete model IDs to catalog target IDs for the
58		// agent.openai surface. Models present in this map are ranked higher during
59		// auto-selection. Populated by the config layer from the model catalog;
60		// nil disables catalog-aware ranking.
61		KnownModels map[string]string
62		Headers     map[string]string // extra HTTP headers (OpenRouter, Azure, etc.)
63		Reasoning   reasoningpolicy.Reasoning
64		// Capabilities supplies provider-owned protocol capability claims. When nil,
65		// direct openai.Provider callers use OpenAI protocol defaults.
66		Capabilities *ProtocolCapabilities
67		// UsageCostAttribution extracts provider-owned gateway cost metadata from
68		// the raw usage object, when that provider reports one.
69		UsageCostAttribution func(rawUsage string) (*agent.CostAttribution, bool)
70		// ModelReasoningWire maps a concrete model ID to the catalog
71		// reasoning_wire value for that model. Recognized values are "provider"
72		// (default), "model_id" (model name encodes reasoning level — strip the
73		// reasoning field at serialization), "none" (model has no reasoning
74		// surface — reject explicit non-off requests pre-flight), "effort"
75		// (always emit reasoning.effort string), and "tokens" (always emit
76		// reasoning.max_tokens int). Models not listed default to "provider",
77		// preserving existing behavior.
78		ModelReasoningWire map[string]string
79		// Logger is used for structured diagnostic logging. When nil, slog.Default() is used.
80		Logger *slog.Logger
81		// QuotaHeaderParser, when set, overrides the default OpenAI rate-limit
82		// header parser. OpenRouter uses this to install
83		// quotaheaders.ParseOpenRouter even though it goes through this
84		// OpenAI-compatible provider implementation.
85		QuotaHeaderParser func(http.Header, time.Time) quotaheaders.Signal
86		// QuotaSignalObserver receives parsed rate-limit signals on every
87		// response. The service layer wires this to the provider quota state
88		// machine. Both QuotaHeaderParser and QuotaSignalObserver must be set
89		// for header-driven exhaustion tracking to activate.
90		QuotaSignalObserver func(quotaheaders.Signal)
91	}
