93	// New creates a new OpenAI-compatible provider.
94	func New(cfg Config) *Provider {
95		serverAddress, serverPort := endpointMetadata(cfg.BaseURL)
96		providerSystem := "openai"
97		if cfg.ProviderSystem != "" {
98			providerSystem = cfg.ProviderSystem
99		}
100		providerName := cfg.ProviderName
101		if providerName == "" {
102			providerName = providerSystem
103		}
104		parser := cfg.QuotaHeaderParser
105		if parser == nil && cfg.QuotaSignalObserver != nil {
106			// Default to OpenAI-shaped header parsing when no explicit parser is
107			// supplied. OpenRouter overrides this via Config.QuotaHeaderParser.
108			parser = quotaheaders.ParseOpenAI
109		}
110		p := &Provider{
111			client: openaicompat.NewClient(openaicompat.Config{
112				BaseURL:             cfg.BaseURL,
113				APIKey:              cfg.APIKey,
114				Headers:             cfg.Headers,
115				QuotaHeaderParser:   parser,
116				QuotaSignalObserver: cfg.QuotaSignalObserver,
117			}),
118			model:              cfg.Model,
119			modelPattern:       cfg.ModelPattern,
120			knownModels:        cfg.KnownModels,
121			baseURL:            cfg.BaseURL,
122			apiKey:             cfg.APIKey,
123			providerName:       providerName,
124			providerSystem:     providerSystem,
125			capabilities:       cfg.Capabilities,
126			usageCost:          cfg.UsageCostAttribution,
127			serverAddress:      serverAddress,
128			serverPort:         serverPort,
129			reasoningDefault:   cfg.Reasoning,
130			modelReasoningWire: cfg.ModelReasoningWire,
131			logger:             cfg.Logger,
132		}
133		if p.logger == nil {
134			p.logger = slog.Default()
135		}
136		return p
137	}
