139	// DiscoveredModels returns the full ranked list of models discovered from the
140	// server's /v1/models endpoint. Returns nil if the provider has a statically
141	// configured model or if discovery has not yet run (i.e. no request has been
142	// made yet). Call EnsureDiscovered to force discovery without making a chat
143	// request.
144	func (p *Provider) DiscoveredModels() []ScoredModel {
145		return p.discoveredModels
146	}
