236	// ChatStream implements agent.StreamingProvider for token-level streaming.
237	func (p *Provider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
238		model, err := p.resolveModel(ctx)
239		if err != nil {
240			return nil, err
241		}
242		if opts.Model != "" {
243			model = opts.Model
244		}
245	
246		reqOpts, err := p.compatRequestOptions(model, opts)
247		if err != nil {
248			return nil, err
249		}
250	
251		return p.client.ChatStream(ctx, model, messages, tools, reqOpts, openaicompat.StreamHooks{
252			Cost: p.costAttribution,
253			Attempt: func(responseModel string, cost *agent.CostAttribution) *agent.AttemptMetadata {
254				return p.attemptMetadata(model, responseModel, streamAttemptCost(cost))
255			},
256		})
257	}
