259	// compatRequestOptions is the canonical openai-compat wire-field assembler
260	// and, per ADR-007 §3, the architectural home for any future
261	// (model_family × reasoning_state × profile) sampling-composition rule.
262	// Reasoning policy and the resolved sampling profile both reach this seam;
263	// when a profile field needs to be clipped or substituted because the
264	// model is in a thinking state (or vice-versa), the rule lives here — not
265	// in the resolver, not in the catalog.
266	//
267	// v1 ships without an active composition rule. The seeded "code" profile
268	// (T=0.6, top_p=0.95, top_k=20) matches Qwen3.x's published thinking-mode
269	// precise-coding recommendation exactly, and is also non-greedy enough to
270	// be safe in the non-thinking-mode case. When a future profile adds a
271	// value that diverges between thinking and non-thinking states for some
272	// family, add the clip rule here; for now, all five sampler fields pass
273	// through unchanged regardless of reasoning state.
274	func (p *Provider) compatRequestOptions(model string, opts agent.Options) (openaicompat.RequestOptions, error) {
275		extra, err := p.reasoningRequestOptions(model, opts)
276		if err != nil {
277			return openaicompat.RequestOptions{}, err
278		}
279		temperature := opts.Temperature
280		topP := opts.TopP
281		if nativeOpenAIUsesDefaultSamplingOnly(p.providerSystem, model) {
282			temperature = nil
283			topP = nil
284		}
285		// Non-standard sampling fields (top_k, min_p, repetition_penalty) ride
286		// as top-level body extras on OpenAI-compatible local/provider wires.
287		// OpenAI proper rejects these as unknown parameters, so only send them
288		// to compatibility providers that are known to accept them.
289		if p.providerSystem != "openai" {
290			if opts.TopK != nil {
291				extra = append(extra, option.WithJSONSet("top_k", *opts.TopK))
292			}
293			if opts.MinP != nil {
294				extra = append(extra, option.WithJSONSet("min_p", *opts.MinP))
295			}
296			if opts.RepetitionPenalty != nil {
297				extra = append(extra, option.WithJSONSet("repetition_penalty", *opts.RepetitionPenalty))
298			}
299		}
300		return openaicompat.RequestOptions{
301			MaxTokens:         opts.MaxTokens,
302			Temperature:       temperature,
303			TopP:              topP,
304			TopK:              opts.TopK,
305			MinP:              opts.MinP,
306			RepetitionPenalty: opts.RepetitionPenalty,
307			Seed:              opts.Seed,
308			Stop:              opts.Stop,
309			ExtraOptions:      extra,
310			CachePolicy:       opts.CachePolicy,
311		}, nil
312	}
