345	// reasoningRequestOptions builds per-request options. For thinking models
346	// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
347	// only when the concrete provider declares the matching wire support.
348	func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, error) {
349		policy, err := reasoningpolicy.Parse(opts.Reasoning)
350		if err != nil {
351			return nil, err
352		}
353		explicitRequest := policy.IsSet()
354		if !explicitRequest {
355			policy, err = reasoningpolicy.Parse(p.reasoningDefault)
356			if err != nil {
357				return nil, err
358			}
359		}
360	
361		if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
362			return nil, nil
363		}
364	
365		// Catalog reasoning_wire metadata gates the wire shape before any
366		// provider-specific encoding runs. Models flagged as reasoning_wire=none
367		// have no reasoning surface at all; an explicit non-off request is a
368		// catalog/wire mismatch and must surface as an error rather than be
369		// silently dropped. Models flagged as reasoning_wire=model_id encode the
370		// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
371		// upstream endpoint cannot honor an external reasoning toggle, so the
372		// reasoning field must be stripped from the wire body.
373		catalogWire := p.modelReasoningWireFor(model)
374		switch catalogWire {
375		case "none":
376			if explicitRequest && !policy.IsExplicitOff() {
377				return nil, fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
378			}
379			return nil, nil
380		case "model_id":
381			return nil, nil
382		}
383	
384		if !p.SupportsThinking() {
385			if policy.IsExplicitOff() {
386				return nil, nil
387			}
388			if explicitRequest {
389				return nil, fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
390			}
391			return nil, nil
392		}
393	
394		if policy.IsExplicitOff() {
395			switch p.thinkingWireFormat() {
396			case ThinkingWireFormatQwen:
397				if !isQwenModel(model) {
398					if explicitRequest && p.strictThinkingModelMatch() {
399						return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
400					}
401					return nil, nil
402				}
403				return []option.RequestOption{
404					option.WithJSONSet("enable_thinking", false),
405					option.WithJSONSet("thinking_budget", 0),
406				}, nil
407			case ThinkingWireFormatOpenRouter:
408				return []option.RequestOption{option.WithJSONSet("reasoning", map[string]interface{}{
409					"effort": "none",
410				})}, nil
411			}
412			return nil, nil
413		}
414	
415		if p.thinkingWireFormat() == ThinkingWireFormatOpenRouter {
416			return openRouterReasoningOptions(policy, catalogWire)
417		}
418		if p.thinkingWireFormat() == ThinkingWireFormatQwen && !isQwenModel(model) {
419			if explicitRequest && p.strictThinkingModelMatch() {
420				return nil, fmt.Errorf("openai: qwen reasoning control is not supported for model %q on provider type %q", model, p.providerSystem)
421			}
422			return nil, nil
423		}
424	
425		// Qwen and ThinkingMap providers can only express a token budget on the
426		// wire. If the catalog declares effort wire for this model, degrade
427		// gracefully: snap KindTokens to the nearest PortableBudgets tier so the
428		// downstream budget calculation uses a standard value. The model still
429		// works; the catalog entry is simply mis-classified.
430		if catalogWire == "effort" {
431			p.logger.Warn("catalog declares effort wire but provider only supports budget wire",
432				"model", model,
433				"provider", p.providerSystem,
434			)
435			if policy.Kind == reasoningpolicy.KindTokens {
436				tier := reasoningpolicy.NearestTierForTokens(policy.Tokens)
437				policy = reasoningpolicy.Policy{Kind: reasoningpolicy.KindNamed, Value: tier}
438			}
439		}
440	
441		thinkingBudget, err := reasoningpolicy.BudgetFor(policy, nil, 0)
442		if err != nil {
443			return nil, fmt.Errorf("openai: %w", err)
444		}
445		if thinkingBudget <= 0 {
446			return nil, nil
447		}
448	
449		switch p.thinkingWireFormat() {
450		case ThinkingWireFormatQwen:
451			return []option.RequestOption{
452				option.WithJSONSet("enable_thinking", true),
453				option.WithJSONSet("thinking_budget", thinkingBudget),
454			}, nil
455		case "", ThinkingWireFormatThinkingMap:
456			return []option.RequestOption{option.WithJSONSet("thinking", map[string]interface{}{
457				"type":          "enabled",
458				"budget_tokens": thinkingBudget,
459			})}, nil
460		default:
461			return nil, fmt.Errorf("openai: unsupported thinking wire format %q for provider type %q", p.thinkingWireFormat(), p.providerSystem)
462		}
463	}
464	
465	// modelReasoningWireFor returns the catalog reasoning_wire value for the
466	// given model, defaulting to "provider" when the model is not catalog-known.
467	// Returned values are normalized: only "model_id" and "none" trigger
468	// catalog-driven wire overrides; everything else falls through to the
469	// provider's protocol capability path.
470	func (p *Provider) modelReasoningWireFor(model string) string {
471		if p.modelReasoningWire == nil || model == "" {
472			return ""
473		}
474		return p.modelReasoningWire[model]
475	}
476	
477	func isQwenModel(model string) bool {
478		return strings.Contains(strings.ToLower(model), "qwen")
479	}
480	
481	// openRouterReasoningOptions builds the OpenRouter nested reasoning object.
482	// wire is the catalog reasoning_wire value for the model:
483	//   - "" or "provider": pick wire shape from policy.Kind (backwards-compat)
484	//   - "effort": always emit reasoning.effort string; snap KindTokens to nearest tier
485	//   - "tokens": always emit reasoning.max_tokens int; expand KindNamed via PortableBudgets
486	func openRouterReasoningOptions(policy reasoningpolicy.Policy, wire string) ([]option.RequestOption, error) {
487		reasoning := map[string]interface{}{}
488		switch wire {
489		case "effort":
490			var tier reasoningpolicy.Reasoning
491			switch policy.Kind {
492			case reasoningpolicy.KindTokens:
493				tier = reasoningpolicy.NearestTierForTokens(policy.Tokens)
494			case reasoningpolicy.KindNamed:
495				tier = policy.Value
496				if tier == reasoningpolicy.ReasoningMax {
497					tier = reasoningpolicy.ReasoningXHigh
498				}
499			default:
500				return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q for effort wire", policy.Kind)
501			}
502			effort := string(tier)
503			switch effort {
504			case "minimal", "low", "medium", "high", "xhigh":
505				reasoning["effort"] = effort
506			default:
507				return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning effort %q", tier)
508			}
509		case "tokens":
510			var budget int
511			switch policy.Kind {
512			case reasoningpolicy.KindTokens:
513				budget = policy.Tokens
514			case reasoningpolicy.KindNamed:
515				budget = reasoningpolicy.BudgetForNamed(policy.Value)
516				if budget <= 0 {
517					return nil, fmt.Errorf("openai: named reasoning %q has no portable token budget for tokens wire", policy.Value)
518				}
519			default:
520				return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q for tokens wire", policy.Kind)
521			}
522			reasoning["max_tokens"] = budget
523		default:
524			// "" or "provider": today's behavior — pick wire shape from policy.Kind.
525			switch policy.Kind {
526			case reasoningpolicy.KindTokens:
527				reasoning["max_tokens"] = policy.Tokens
528			case reasoningpolicy.KindNamed:
529				effort := string(policy.Value)
530				if policy.Value == reasoningpolicy.ReasoningMax {
531					effort = string(reasoningpolicy.ReasoningXHigh)
532				}
533				switch effort {
534				case "minimal", "low", "medium", "high", "xhigh":
535					reasoning["effort"] = effort
536				default:
537					return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning effort %q", policy.Value)
538				}
539			default:
540				return nil, fmt.Errorf("openai: unsupported OpenRouter reasoning policy %q", policy.Kind)
541			}
542		}
543		return []option.RequestOption{option.WithJSONSet("reasoning", reasoning)}, nil
544	}
