549	func endpointMetadata(baseURL string) (serverAddress string, serverPort int) {
550		serverAddress = "api.openai.com"
551		serverPort = 443
552	
553		if baseURL == "" {
554			return serverAddress, serverPort
555		}
556	
557		parsed, err := url.Parse(baseURL)
558		if err != nil {
559			return serverAddress, serverPort
560		}
561	
562		host := parsed.Hostname()
563		if host != "" {
564			serverAddress = host
565		}
566	
567		if port := parsed.Port(); port != "" {
568			if parsedPort, err := strconv.Atoi(port); err == nil {
569				serverPort = parsedPort
570			}
571		} else if strings.EqualFold(parsed.Scheme, "http") {
572			serverPort = 80
573		}
574	
575		return serverAddress, serverPort
576	}
